=== FILE: logger.ts ===
import { writeFileSync, appendFileSync } from "node:fs";

export enum LogLevel {
  ERROR = 0,
  WARN = 1,
  INFO = 2,
  DEBUG = 3,
}

export interface LoggerOptions {
  enabled: boolean;
  level: LogLevel;
  logFile: string;
}

export class Logger {
  private options: LoggerOptions;

  constructor(options: LoggerOptions) {
    this.options = options;
    if (options.enabled) {
      writeFileSync(options.logFile, "=== LOG START ===\n", "utf-8");
    }
  }

  // shouldLog 仅用于 console 输出过滤
  private shouldLog(level: LogLevel): boolean {
    return this.options.enabled && level <= this.options.level;
  }

  log(level: LogLevel, message: string): void {
    if (!this.options.enabled) return;
    const line = `[${LogLevel[level]}] ${message}\n`;
    // file 总是写入所有级别
    appendFileSync(this.options.logFile, line);
    // console 输出受 level 过滤
    if (this.shouldLog(level)) {
      process.stdout.write(line);
    }
  }
}

